function wateringGroup(p) {
  if (['tree', 'shrub', 'fruit-tree', 'nut', 'vine'].includes(p.category)) return 'woody';
  if (p.category === 'berry') return p.planting.matureHeightCm?.max > 60 ? 'woody' : 'perennial';
  if (p.tags.includes('overwinter-indoors') || p.tags.includes('tender-perennial')) return 'container';
  if (['vegetable', 'fruit', 'green-manure'].includes(p.category)) return 'veg';
  if (p.category === 'herb') return p.lifecycle === 'perennial' ? 'perennial' : 'veg';
  return 'perennial';
}

