/** Fills only what a record lacks. */
export function applyEnrichment(plants) {
  const byId = new Map(plants.map((p) => [p.id, p]));
  const set = (obj, key, value) => {
    if (value === undefined) return false;
    const cur = obj[key];
    if (cur == null || (Array.isArray(cur) && cur.length === 0)) {
      obj[key] = value;
      return true;
    }
    return false;
  };
  const range = (v) => (v ? R(v[0], v[1]) : undefined);
  for (const [id, e] of Object.entries(ENRICH)) {
    const p = byId.get(id);
    if (!p) throw new Error(`Enrichment for unknown plant ${id}`);
    let changed = false;
    changed = set(p.growing, 'ph', range(e.ph)) || changed;
    changed = set(p.growing, 'soil', e.soil) || changed;
    changed = set(p.planting, 'matureHeightCm', range(e.h)) || changed;
    changed = set(p.planting, 'matureWidthCm', range(e.w)) || changed;
    changed = set(p.planting, 'rootDepth', e.root) || changed;
    changed = set(p.planting, 'seedDepthCm', range(e.sd)) || changed;
    changed = set(p.planting, 'plantingDepthCm', range(e.pd)) || changed;
    changed = set(p.care, 'feeding', e.feed) || changed;
    changed = set(p.care, 'pests', e.pests) || changed;
    changed = set(p.care, 'diseases', e.dis) || changed;
    changed = set(p.care, 'harvesting', e.harv) || changed;
    changed = set(p.care, 'watering', e.water) || changed;
    if (e.y && !p.yield) {
      p.yield = {
        ...(e.y.plant ? { perPlantKg: range(e.y.plant) } : {}),
        ...(e.y.m2 ? { perM2Kg: range(e.y.m2) } : {}),
        assumptions: e.y.a ?? t('Typical home-garden range; varies with variety, season and care.', 'Tyypillinen kotipuutarhan vaihteluväli; riippuu lajikkeesta, kesästä ja hoidosta.'),
        confidence: 'low',
      };
      changed = true;
    }
    if (changed) p.provenance.updated = ENRICHED;
  }
  // Watering advice follows the record's own water need.
  for (const p of plants) {
    if (p.care.watering || !p.growing.water) continue;
    p.care.watering = W[wateringGroup(p)][p.growing.water];
  }
}

